using System.Security.Claims;
using BrewNest.Contracts.Production;
using BrewNest.Modules.Production.Application.Interfaces;
using BrewNest.Modules.Production.Domain.Entities;
using BrewNest.Modules.Production.Infrastructure.Persistence;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;

namespace BrewNest.Modules.Production.Application.Services;

internal enum ProductionResultStatus { Success, Validation, NotFound, Conflict }
internal sealed record ProductionResult<T>(ProductionResultStatus Status,T? Value,string[] Errors) { public bool Succeeded=>Status==ProductionResultStatus.Success; public static ProductionResult<T> Success(T value)=>new(ProductionResultStatus.Success,value,[]); public static ProductionResult<T> Failure(ProductionResultStatus status,params string[] errors)=>new(status,default,errors); }
internal sealed record ProductionRequestContext(string Actor) { public static ProductionRequestContext FromHttpContext(HttpContext context)=>new(context.User.FindFirstValue(ClaimTypes.NameIdentifier)??context.User.Identity?.Name??"anonymous"); }

internal sealed class ProductionService(ProductionDbContext database,IProductionRecipePort recipes,IProductionInventoryPort inventory,IProductionDocumentNumberPort numbers,TimeProvider timeProvider)
{
    private DateTimeOffset Now=>timeProvider.GetUtcNow();
    public async Task<ProductionResult<ProductionMenuItemReference[]>> GetReferencesAsync(CancellationToken token)=>ProductionResult<ProductionMenuItemReference[]>.Success(await recipes.GetMenuItemsAsync(token));
    public async Task<ProductionResult<ProductionCatalogItemReference[]>> GetItemNamesAsync(CancellationToken token)=>ProductionResult<ProductionCatalogItemReference[]>.Success(await recipes.GetItemNamesAsync(token));
    public async Task<ProductionResult<ProductionPlanResponse[]>> GetPlansAsync(CancellationToken token){var values=await database.Plans.AsNoTracking().Include(x=>x.Lines).OrderByDescending(x=>x.PlannedDate).ThenByDescending(x=>x.CreatedAt).ToArrayAsync(token);return ProductionResult<ProductionPlanResponse[]>.Success(values.Select(Map).ToArray());}
    public async Task<ProductionResult<ProductionPlanResponse>> GetPlanAsync(Guid id,CancellationToken token){var value=await database.Plans.AsNoTracking().Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,token);return value is null?NotFound<ProductionPlanResponse>("The production plan was not found."):ProductionResult<ProductionPlanResponse>.Success(Map(value));}
    public async Task<ProductionResult<ProductionOrderResponse[]>> GetOrdersAsync(Guid? planId,string? status,CancellationToken token){var query=database.Orders.AsNoTracking().Include(x=>x.Requirements).AsQueryable();if(planId is not null)query=query.Where(x=>x.PlanId==planId);if(!string.IsNullOrWhiteSpace(status)){if(!Enum.TryParse<OrderStatus>(status,true,out var parsed))return Validation<ProductionOrderResponse[]>("The production order status is invalid.");query=query.Where(x=>x.Status==parsed);}var values=await query.OrderByDescending(x=>x.CreatedAt).ToArrayAsync(token);return ProductionResult<ProductionOrderResponse[]>.Success(values.Select(Map).ToArray());}
    public async Task<ProductionResult<ProductionOrderResponse>> GetOrderAsync(Guid id,CancellationToken token){var value=await database.Orders.AsNoTracking().Include(x=>x.Requirements).SingleOrDefaultAsync(x=>x.Id==id,token);return value is null?NotFound<ProductionOrderResponse>("The production order was not found."):ProductionResult<ProductionOrderResponse>.Success(Map(value));}
    public async Task<ProductionResult<ProductionStatusHistoryResponse[]>> GetHistoryAsync(string? type,Guid? id,CancellationToken token){var query=database.StatusHistory.AsNoTracking();if(!string.IsNullOrWhiteSpace(type))query=query.Where(x=>x.DocumentType==type);if(id is not null)query=query.Where(x=>x.DocumentId==id);var values=await query.OrderByDescending(x=>x.ChangedAt).Take(500).ToArrayAsync(token);return ProductionResult<ProductionStatusHistoryResponse[]>.Success(values.Select(Map).ToArray());}

    public async Task<ProductionResult<ProductionPlanResponse>> CreatePlanAsync(CreateProductionPlanRequest request,ProductionRequestContext context,CancellationToken token)
    {
        var errors=ValidatePlan(request);if(errors.Length>0)return Validation<ProductionPlanResponse>(errors);
        var plan=new ProductionPlan{Id=Guid.NewGuid(),PlanNumber=numbers.NextPlanNumber(),Name=request.Name.Trim(),PlannedDate=request.PlannedDate,Notes=request.Notes.Trim(),Status=PlanStatus.Draft,CreatedAt=Now,CreatedBy=context.Actor};
        foreach(var requested in request.Lines){var line=new ProductionPlanLine{Id=Guid.NewGuid(),PlanId=plan.Id,MenuItemId=requested.MenuItemId,Quantity=requested.Quantity};plan.Lines.Add(line);database.PlanLines.Add(line);}database.Plans.Add(plan);AddHistory("Plan",plan.Id,"None",PlanStatus.Draft.ToString(),"Production plan created.",context);return await SaveAsync(()=>Map(plan),token);
    }

    public async Task<ProductionResult<ProductionPlanResponse>> ReleasePlanAsync(Guid id,ChangeProductionStatusRequest request,ProductionRequestContext context,CancellationToken token)
    {
        var plan=await database.Plans.AsSplitQuery().Include(x=>x.Lines).Include(x=>x.Orders).SingleOrDefaultAsync(x=>x.Id==id,token);if(plan is null)return NotFound<ProductionPlanResponse>("The production plan was not found.");if(plan.Status!=PlanStatus.Draft)return Conflict<ProductionPlanResponse>("Only draft production plans may be released.");if(!ApplyVersion(plan,request.Version))return VersionFailure<ProductionPlanResponse>();if(!ValidReason(request.Reason))return Validation<ProductionPlanResponse>("A release reason up to 500 characters is required.");
        var snapshots=new Dictionary<Guid,ProductionRecipeSnapshot>();foreach(var line in plan.Lines){var recipe=await recipes.GetRecipeAsync(line.MenuItemId,token);if(recipe is null||recipe.YieldQuantity<=0||recipe.Ingredients.Length==0)return Conflict<ProductionPlanResponse>("A selected menu item has no active recipe. Add or activate its recipe in Catalog, then try again.");snapshots[line.Id]=recipe;}
        foreach(var line in plan.Lines){var recipe=snapshots[line.Id];var order=new ProductionOrder{Id=Guid.NewGuid(),OrderNumber=numbers.NextOrderNumber(),PlanId=plan.Id,PlanLineId=line.Id,MenuItemId=line.MenuItemId,PlannedQuantity=line.Quantity,Status=OrderStatus.Draft,CreatedAt=Now,CreatedBy=context.Actor};foreach(var group in recipe.Ingredients.GroupBy(x=>x.ItemId)){var baseQuantity=Round(group.Sum(x=>x.Quantity/recipe.YieldQuantity*line.Quantity));var expectedWastage=Round(group.Sum(x=>x.Quantity/recipe.YieldQuantity*line.Quantity*x.WastagePercentage/100m));var requirement=new ProductionMaterialRequirement{Id=Guid.NewGuid(),OrderId=order.Id,IngredientItemId=group.Key,BomQuantity=baseQuantity,ExpectedWastage=expectedWastage,RequiredQuantity=baseQuantity+expectedWastage};order.Requirements.Add(requirement);database.Requirements.Add(requirement);}plan.Orders.Add(order);database.Orders.Add(order);AddHistory("Order",order.Id,"None",OrderStatus.Draft.ToString(),"Generated from released production plan.",context);}
        var previous=plan.Status;plan.Status=PlanStatus.Released;Touch(plan,context);AddHistory("Plan",plan.Id,previous.ToString(),plan.Status.ToString(),request.Reason,context);return await SaveAsync(()=>Map(plan),token);
    }

    public async Task<ProductionResult<ProductionPlanResponse>> CancelPlanAsync(Guid id,ChangeProductionStatusRequest request,ProductionRequestContext context,CancellationToken token)
    {
        var plan=await database.Plans.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,token);if(plan is null)return NotFound<ProductionPlanResponse>("The production plan was not found.");if(plan.Status!=PlanStatus.Draft)return Conflict<ProductionPlanResponse>("Only a draft plan may be cancelled.");if(!ApplyVersion(plan,request.Version))return VersionFailure<ProductionPlanResponse>();if(!ValidReason(request.Reason))return Validation<ProductionPlanResponse>("A cancellation reason up to 500 characters is required.");var previous=plan.Status;plan.Status=PlanStatus.Cancelled;Touch(plan,context);AddHistory("Plan",plan.Id,previous.ToString(),plan.Status.ToString(),request.Reason,context);return await SaveAsync(()=>Map(plan),token);
    }

    public async Task<ProductionResult<ProductionOrderResponse>> ReleaseOrderAsync(Guid id,ChangeProductionStatusRequest request,ProductionRequestContext context,CancellationToken token)
    {
        var order=await FullOrder().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<ProductionOrderResponse>("The production order was not found.");if(order.Status!=OrderStatus.Draft)return Conflict<ProductionOrderResponse>("Only draft production orders may be released.");if(!ApplyVersion(order,request.Version))return VersionFailure<ProductionOrderResponse>();if(!ValidReason(request.Reason))return Validation<ProductionOrderResponse>("A release reason up to 500 characters is required.");var reserved=await inventory.ReserveAsync(order.Id.ToString("N"),order.Requirements.Select(x=>new ProductionInventoryRequirement(x.IngredientItemId,x.RequiredQuantity)).ToArray(),context.Actor,token);if(!reserved.Succeeded)return Conflict<ProductionOrderResponse>(reserved.Errors);var previous=order.Status;order.Status=OrderStatus.Released;Touch(order,context);AddHistory("Order",order.Id,previous.ToString(),order.Status.ToString(),request.Reason,context);var saved=await SaveAsync(()=>Map(order),token);if(!saved.Succeeded)await inventory.ReleaseAsync(order.Id.ToString("N"),"Production order release persistence failed.",context.Actor,token);return saved;
    }

    public async Task<ProductionResult<ProductionOrderResponse>> IssueMaterialsAsync(Guid id,IssueProductionMaterialsRequest request,ProductionRequestContext context,CancellationToken token)
    {
        var order=await FullOrder().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<ProductionOrderResponse>("The production order was not found.");if(order.Status!=OrderStatus.Released)return Conflict<ProductionOrderResponse>("Materials may be issued only for a released production order.");if(!ApplyVersion(order,request.Version))return VersionFailure<ProductionOrderResponse>();if(!ValidReason(request.Reason))return Validation<ProductionOrderResponse>("An issue reason up to 500 characters is required.");if(request.Materials.Length!=order.Requirements.Count||request.Materials.Select(x=>x.IngredientItemId).Distinct().Count()!=request.Materials.Length||request.Materials.Any(x=>x.ActualConsumption<0||x.Wastage<0||x.ActualConsumption+x.Wastage<=0)||request.Materials.Select(x=>x.IngredientItemId).Order().SequenceEqual(order.Requirements.Select(x=>x.IngredientItemId).Order())==false)return Validation<ProductionOrderResponse>("Provide one positive actual-consumption/wastage entry for every material requirement.");
        var issued=await inventory.IssueAsync(order.Id.ToString("N"),request.Materials.Select(x=>new ProductionInventoryUsage(x.IngredientItemId,x.ActualConsumption,x.Wastage)).ToArray(),context.Actor,token);if(!issued.Succeeded)return Conflict<ProductionOrderResponse>(issued.Errors);
        foreach(var usage in request.Materials){var requirement=order.Requirements.Single(x=>x.IngredientItemId==usage.IngredientItemId);requirement.ActualConsumption=usage.ActualConsumption;requirement.ActualWastage=usage.Wastage;requirement.Variance=Round(usage.ActualConsumption+usage.Wastage-requirement.RequiredQuantity);}
        var previous=order.Status;order.Status=OrderStatus.InProgress;Touch(order,context);AddHistory("Order",order.Id,previous.ToString(),order.Status.ToString(),request.Reason,context);return await SaveAsync(()=>Map(order),token);
    }

    public async Task<ProductionResult<ProductionOrderResponse>> CompleteOrderAsync(Guid id,ChangeProductionStatusRequest request,ProductionRequestContext context,CancellationToken token)
    {
        var order=await FullOrder().Include(x=>x.Plan).ThenInclude(x=>x.Orders).SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<ProductionOrderResponse>("The production order was not found.");if(order.Status!=OrderStatus.InProgress)return Conflict<ProductionOrderResponse>("Only an in-progress production order may be completed.");if(!ApplyVersion(order,request.Version))return VersionFailure<ProductionOrderResponse>();if(!ValidReason(request.Reason))return Validation<ProductionOrderResponse>("A completion reason up to 500 characters is required.");var previous=order.Status;order.Status=OrderStatus.Completed;order.CompletedAt=Now;Touch(order,context);AddHistory("Order",order.Id,previous.ToString(),order.Status.ToString(),request.Reason,context);if(order.Plan.Orders.All(x=>x.Id==order.Id||x.Status==OrderStatus.Completed)){var planPrevious=order.Plan.Status;order.Plan.Status=PlanStatus.Completed;Touch(order.Plan,context);AddHistory("Plan",order.Plan.Id,planPrevious.ToString(),order.Plan.Status.ToString(),"All production orders completed.",context);}return await SaveAsync(()=>Map(order),token);
    }

    public async Task<ProductionResult<ProductionOrderResponse>> CancelOrderAsync(Guid id,ChangeProductionStatusRequest request,ProductionRequestContext context,CancellationToken token)
    {
        var order=await FullOrder().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<ProductionOrderResponse>("The production order was not found.");if(order.Status is not (OrderStatus.Draft or OrderStatus.Released))return Conflict<ProductionOrderResponse>("An order cannot be cancelled after material issue; use reversal or wastage transactions.");if(!ApplyVersion(order,request.Version))return VersionFailure<ProductionOrderResponse>();if(!ValidReason(request.Reason))return Validation<ProductionOrderResponse>("A cancellation reason up to 500 characters is required.");if(order.Status==OrderStatus.Released){var released=await inventory.ReleaseAsync(order.Id.ToString("N"),request.Reason,context.Actor,token);if(!released.Succeeded)return Conflict<ProductionOrderResponse>(released.Errors);}var previous=order.Status;order.Status=OrderStatus.Cancelled;Touch(order,context);AddHistory("Order",order.Id,previous.ToString(),order.Status.ToString(),request.Reason,context);return await SaveAsync(()=>Map(order),token);
    }

    private IQueryable<ProductionOrder> FullOrder()=>database.Orders.AsSplitQuery().Include(x=>x.Requirements);
    private static string[] ValidatePlan(CreateProductionPlanRequest r){var errors=new List<string>();if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Trim().Length>200)errors.Add("A plan name up to 200 characters is required.");if(r.Notes is null||r.Notes.Length>1000)errors.Add("Plan notes cannot exceed 1000 characters.");if(r.Lines.Length==0)errors.Add("At least one production plan line is required.");if(r.Lines.Any(x=>x.MenuItemId==Guid.Empty||x.Quantity<=0))errors.Add("Every plan line needs a menu item and positive quantity.");if(r.Lines.Select(x=>x.MenuItemId).Distinct().Count()!=r.Lines.Length)errors.Add("A menu item may appear only once in a plan.");return errors.ToArray();}
    private void AddHistory(string type,Guid id,string previous,string next,string reason,ProductionRequestContext context)=>database.StatusHistory.Add(new(){Id=Guid.NewGuid(),DocumentType=type,DocumentId=id,PreviousStatus=previous,NewStatus=next,Reason=reason.Trim(),ChangedBy=context.Actor,ChangedAt=Now});
    private void Touch(ProductionPlan x,ProductionRequestContext c){x.ModifiedAt=Now;x.ModifiedBy=c.Actor;}private void Touch(ProductionOrder x,ProductionRequestContext c){x.ModifiedAt=Now;x.ModifiedBy=c.Actor;}
    private bool ApplyVersion(ProductionPlan x,string version)=>ApplyVersionCore(database.Entry(x).Property(y=>y.RowVersion),version);private bool ApplyVersion(ProductionOrder x,string version)=>ApplyVersionCore(database.Entry(x).Property(y=>y.RowVersion),version);private static bool ApplyVersionCore<TEntity>(Microsoft.EntityFrameworkCore.ChangeTracking.PropertyEntry<TEntity,byte[]> property,string version) where TEntity:class{try{var bytes=Convert.FromBase64String(version);if(bytes.Length==0&&property.CurrentValue.Length==0)return true;property.OriginalValue=bytes;return bytes.Length>0;}catch(FormatException){return false;}}
    private async Task<ProductionResult<T>> SaveAsync<T>(Func<T> factory,CancellationToken token){try{await database.SaveChangesAsync(token);return ProductionResult<T>.Success(factory());}catch(DbUpdateConcurrencyException){return VersionFailure<T>();}catch(DbUpdateException){return Conflict<T>("The production change conflicts with current data.");}}
    private static decimal Round(decimal value)=>decimal.Round(value,3,MidpointRounding.AwayFromZero);private static bool ValidReason(string? value)=>!string.IsNullOrWhiteSpace(value)&&value.Trim().Length<=500;private static string Version(byte[] x)=>Convert.ToBase64String(x);
    private static ProductionPlanResponse Map(ProductionPlan x)=>new(x.Id,x.PlanNumber,x.Name,x.PlannedDate,x.Notes,(ProductionPlanStatus)x.Status,x.Lines.Select(y=>new ProductionPlanLineResponse(y.Id,y.MenuItemId,y.Quantity)).ToArray(),x.CreatedAt,x.CreatedBy,Version(x.RowVersion));
    private static ProductionOrderResponse Map(ProductionOrder x)=>new(x.Id,x.OrderNumber,x.PlanId,x.PlanLineId,x.MenuItemId,x.PlannedQuantity,(ProductionOrderStatus)x.Status,x.Requirements.Select(y=>new ProductionMaterialRequirementResponse(y.Id,y.IngredientItemId,y.BomQuantity,y.ExpectedWastage,y.RequiredQuantity,y.ActualConsumption,y.ActualWastage,y.Variance,Version(y.RowVersion))).ToArray(),x.CreatedAt,x.CreatedBy,x.CompletedAt,Version(x.RowVersion));
    private static ProductionStatusHistoryResponse Map(ProductionStatusHistory x)=>new(x.Id,x.DocumentType,x.DocumentId,x.PreviousStatus,x.NewStatus,x.Reason,x.ChangedBy,x.ChangedAt);
    private static ProductionResult<T> Validation<T>(params string[] e)=>ProductionResult<T>.Failure(ProductionResultStatus.Validation,e);private static ProductionResult<T> NotFound<T>(params string[] e)=>ProductionResult<T>.Failure(ProductionResultStatus.NotFound,e);private static ProductionResult<T> Conflict<T>(params string[] e)=>ProductionResult<T>.Failure(ProductionResultStatus.Conflict,e);private static ProductionResult<T> VersionFailure<T>()=>Conflict<T>("The production record changed. Reload it and try again.");
}
